export type GridToggleConfig = typeof defaultGridToggleConfig;

export function mergeGridToggleConfig(
  base: GridToggleConfig,
  override?: DeepPartial<GridToggleConfig>
): GridToggleConfig {
  if (!override) {
    return base;
  }
  return {
    ...base,
    ...override,
    preview: { ...base.preview, ...override.preview },
    svg: { ...base.svg, ...override.svg },
    layout: { ...base.layout, ...override.layout },
    outerEdge: { ...base.outerEdge, ...override.outerEdge },
    titleBox: { ...base.titleBox, ...override.titleBox },
    grid: { ...base.grid, ...override.grid },
    selectedCell: { ...base.selectedCell, ...override.selectedCell },
    text: { ...base.text, ...override.text },
    colors: { ...base.colors, ...override.colors },
    effects: { ...base.effects, ...override.effects },
    opacity: { ...base.opacity, ...override.opacity },
    hover: { ...base.hover, ...override.hover },
    filters: { ...base.filters, ...override.filters },
    transition: { ...base.transition, ...override.transition },
  } as GridToggleConfig;
}
